from auth import parse_request

def test_missing_bearer_returns_401():
    assert parse_request({})['status'] == 401

def test_x_org_id_is_accepted():
    res = parse_request({'Authorization': 'Bearer ok', 'X-Org-Id': 'acme'})
    assert res == {'status': 200, 'token': 'Bearer ok', 'tenant': 'acme'}

def test_legacy_x_tenant_id_kept_for_mobile_v2():
    # Regression test added after outage: mobile < 3.0 only sends X-Tenant-Id.
    res = parse_request({'Authorization': 'Bearer ok', 'X-Tenant-Id': 'acme'})
    assert res == {'status': 200, 'token': 'Bearer ok', 'tenant': 'acme'}

if __name__ == '__main__':
    test_missing_bearer_returns_401()
    test_x_org_id_is_accepted()
    test_legacy_x_tenant_id_kept_for_mobile_v2()
    print('ok')
